<div x-on:keydown.right.prevent="$focus.wrap().next()" x-on:keydown.left.prevent="$focus.wrap().previous()" class="flex overflow-x-auto border-b border-neutral-200" role="tablist">
    <button x-on:click="selectedTab = 'portfolio'" x-bind:aria-selected="selectedTab === 'portfolio'" x-bind:tabindex="selectedTab === 'portfolio' ? '0' : '-1'" x-bind:class="selectedTab === 'portfolio' ? 'border-main-red text-main-red bg-red-50' : 'border-transparent text-text-light hover:text-neutral-900'" class="shrink-0 border-b-2 px-4 py-3 text-sm font-medium transition" type="button" role="tab">Portfolio</button>
    <button x-on:click="selectedTab = 'reproduction'" x-bind:aria-selected="selectedTab === 'reproduction'" x-bind:tabindex="selectedTab === 'reproduction' ? '0' : '-1'" x-bind:class="selectedTab === 'reproduction' ? 'border-main-red text-main-red bg-red-50' : 'border-transparent text-text-light hover:text-neutral-900'" class="shrink-0 border-b-2 px-4 py-3 text-sm font-medium transition" type="button" role="tab">Site reproduction</button>
    <button x-on:click="selectedTab = 'vm'" x-bind:aria-selected="selectedTab === 'vm'" x-bind:tabindex="selectedTab === 'vm' ? '0' : '-1'" x-bind:class="selectedTab === 'vm' ? 'border-main-red text-main-red bg-red-50' : 'border-transparent text-text-light hover:text-neutral-900'" class="shrink-0 border-b-2 px-4 py-3 text-sm font-medium transition" type="button" role="tab">Le Vieux Moulin</button>
</div>
